DROP PROCEDURE IF EXISTS add_migration;
DELIMITER ??
CREATE PROCEDURE `add_migration`()
BEGIN
DECLARE v INT DEFAULT 1;
SET v = (SELECT COUNT(*) FROM `migrations` WHERE `id`='20261012120000');
IF v = 0 THEN

DELETE FROM `bonk_mastery_tree` WHERE `class` IN (1, 2, 3, 4, 5, 7, 11);

DELETE FROM `bonk_mastery` WHERE `class` IN (1, 2, 3, 4, 5, 7, 11);

DELETE FROM `bonk_quest` WHERE `id` BETWEEN 121 AND 190;

END IF;
END??
DELIMITER ;
CALL add_migration();
DROP PROCEDURE IF EXISTS add_migration;
